"""Watcher, reader and offset-store tests -- generated by REVIEW.

Closes coverage_report.md gaps 2, 3, 4 and 6. Before this file,
`queue_tailer.py`, `transcript_poller.py`, `transcript_reader.py` and
`offsets.py` had **no tests at all** -- roughly 190 statements of the most
failure-sensitive logic in the codebase:

* the partial-line / byte-offset arithmetic, where an off-by-one silently
  duplicates or destroys every subsequent record, and
* the persisted offset store, where a mis-save re-ingests from byte 0 and
  double-counts every session aggregate.

## Status: NOT EXECUTED

Written during a review session in which `pytest` was denied by the permission
gate. Nothing here has been run.

The two `run()`-loop tests use a short real sleep to let one poll cycle
complete. If they prove flaky on a loaded machine, raise `_CYCLE_SECONDS` rather
than deleting them -- the error-isolation guarantee they check (PRD section 25)
is a stated product requirement with no other coverage.
"""

from __future__ import annotations

import asyncio
import json
from pathlib import Path

from backend.adapters.claude import transcript_reader
from backend.adapters.claude.adapter import ClaudeAdapter
from backend.shared import paths
from backend.telemetry import queue_tailer, transcript_poller
from backend.telemetry.offsets import OffsetStore
from backend.telemetry.queue_tailer import QueueTailer, read_new_lines
from backend.telemetry.transcript_poller import TranscriptPoller
from backend.telemetry.watcher_status import registry

#: Long enough for one poll cycle (which offloads to a real thread) to finish.
_CYCLE_SECONDS = 0.5


def _append_json_lines(path: Path, *records) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("ab") as handle:
        for record in records:
            handle.write((json.dumps(record) + "\n").encode("utf-8"))


def _append_raw(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("ab") as handle:
        handle.write(text.encode("utf-8"))


class _CollectingPipeline:
    """Stands in for IngestionPipeline; records what the watcher submitted."""

    def __init__(self) -> None:
        self.events: list = []

    async def submit(self, event) -> None:
        self.events.append(event)


# ==========================================================================
# queue_tailer.read_new_lines
# ==========================================================================


def test_reads_complete_lines_and_advances_the_offset(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1}, {"b": 2})

    records, offset = read_new_lines(queue, 0)

    assert records == [{"a": 1}, {"b": 2}]
    assert offset == queue.stat().st_size


def test_a_partial_final_line_is_left_for_the_next_cycle(tmp_path):
    """The hook handler may be mid-append; consuming a half-written line would
    corrupt the offset and therefore every record after it."""
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1})
    complete_size = queue.stat().st_size
    _append_raw(queue, '{"b": 2')  # no trailing newline

    records, offset = read_new_lines(queue, 0)

    assert records == [{"a": 1}]
    assert offset == complete_size, "offset advanced past an incomplete line"


def test_the_partial_line_is_read_once_it_is_completed(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1})
    _append_raw(queue, '{"b": 2')

    _, offset = read_new_lines(queue, 0)
    _append_raw(queue, "}\n")
    records, final_offset = read_new_lines(queue, offset)

    assert records == [{"b": 2}]
    assert final_offset == queue.stat().st_size


def test_resuming_from_an_offset_returns_only_new_records(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1})
    _, offset = read_new_lines(queue, 0)

    _append_json_lines(queue, {"b": 2})
    records, _ = read_new_lines(queue, offset)

    assert records == [{"b": 2}], "already-ingested records were re-read"


def test_no_new_bytes_returns_nothing(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1})
    _, offset = read_new_lines(queue, 0)

    assert read_new_lines(queue, offset) == ([], offset)


def test_a_missing_queue_file_is_not_an_error(tmp_path):
    """A machine that has never run a hook is a normal, supported state."""
    assert read_new_lines(tmp_path / "nope.jsonl", 0) == ([], 0)


def test_a_shrunken_file_restarts_from_zero(tmp_path):
    """Truncation or rotation: reading from a stale offset would be meaningless."""
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1}, {"b": 2})
    stale_offset = queue.stat().st_size

    queue.write_bytes(b'{"c": 3}\n')
    records, offset = read_new_lines(queue, stale_offset)

    assert records == [{"c": 3}]
    assert offset == queue.stat().st_size


def test_a_malformed_line_is_skipped_without_losing_the_rest(tmp_path):
    """PRD user story 3: one bad line must not cost us the file."""
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, {"a": 1})
    _append_raw(queue, "this is not json at all\n")
    _append_json_lines(queue, {"b": 2})

    records, offset = read_new_lines(queue, 0)

    assert records == [{"a": 1}, {"b": 2}]
    assert offset == queue.stat().st_size, "the skipped line must still be consumed"


def test_non_object_json_lines_are_ignored(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_json_lines(queue, [1, 2, 3], "a string", {"a": 1})

    records, _ = read_new_lines(queue, 0)

    assert records == [{"a": 1}]


def test_blank_lines_are_ignored(tmp_path):
    queue = tmp_path / "claude_hooks.jsonl"
    _append_raw(queue, "\n\n")
    _append_json_lines(queue, {"a": 1})

    records, _ = read_new_lines(queue, 0)

    assert records == [{"a": 1}]


