def test_discover_transcripts_on_a_missing_directory_returns_empty(tmp_path):
    """A machine with no Claude Code install must not raise."""
    assert transcript_reader.discover_transcripts(tmp_path / "absent") == []


def test_discover_transcripts_finds_nested_jsonl_files(tmp_path):
    root = tmp_path / "projects"
    (root / "proj-a").mkdir(parents=True)
    (root / "proj-b" / "nested").mkdir(parents=True)
    (root / "proj-a" / "one.jsonl").write_text("", encoding="utf-8")
    (root / "proj-b" / "nested" / "two.jsonl").write_text("", encoding="utf-8")
    (root / "proj-a" / "ignore.txt").write_text("", encoding="utf-8")

    found = transcript_reader.discover_transcripts(root)

    assert [p.name for p in found] == ["one.jsonl", "two.jsonl"]


def test_read_new_records_returns_complete_records_and_offset(tmp_path):
    path = tmp_path / "session.jsonl"
    _append_json_lines(path, {"type": "assistant"}, {"type": "user"})

    batch = transcript_reader.read_new_records(path, 0)

    assert batch.records == [{"type": "assistant"}, {"type": "user"}]
    assert batch.new_offset == path.stat().st_size
    assert batch.path == path


def test_read_new_records_holds_back_a_partial_line(tmp_path):
    """Claude Code appends while we read; a torn tail must be re-read, not lost."""
    path = tmp_path / "session.jsonl"
    _append_json_lines(path, {"type": "assistant"})
    complete_size = path.stat().st_size
    _append_raw(path, '{"type": "assi')

    batch = transcript_reader.read_new_records(path, 0)

    assert batch.records == [{"type": "assistant"}]
    assert batch.new_offset == complete_size


def test_read_new_records_restarts_when_the_file_shrinks(tmp_path):
    path = tmp_path / "session.jsonl"
    _append_json_lines(path, {"type": "assistant"})
    stale = path.stat().st_size + 500

    batch = transcript_reader.read_new_records(path, stale)

    assert batch.records == [{"type": "assistant"}]


def test_read_new_records_skips_malformed_lines(tmp_path):
    path = tmp_path / "session.jsonl"
    _append_raw(path, "{ not json\n")
    _append_json_lines(path, {"type": "assistant"})

    batch = transcript_reader.read_new_records(path, 0)

    assert batch.records == [{"type": "assistant"}]


def test_read_new_records_on_a_missing_file_returns_the_offset_unchanged(tmp_path):
    batch = transcript_reader.read_new_records(tmp_path / "gone.jsonl", 42)

    assert batch.records == []
    assert batch.new_offset == 42


