def test_offsets_round_trip_through_disk(tmp_path):
    path = tmp_path / "tailer_state.json"

    store = OffsetStore(path)
    store.set("/logs/claude_hooks.jsonl", 512)
    store.save()

    reloaded = OffsetStore(path)
    reloaded.load()

    assert reloaded.get("/logs/claude_hooks.jsonl") == 512


def test_an_unknown_key_starts_at_zero(tmp_path):
    store = OffsetStore(tmp_path / "state.json")
    store.load()

    assert store.get("/never/seen.jsonl") == 0


def test_a_missing_state_file_loads_as_empty(tmp_path):
    store = OffsetStore(tmp_path / "absent.json")
    store.load()  # must not raise

    assert store.get("anything") == 0


def test_a_corrupt_state_file_starts_fresh_rather_than_raising(tmp_path):
    """Restarting from 0 duplicates events -- recoverable. Crashing the watcher
    on a corrupt cache file is not."""
    path = tmp_path / "state.json"
    path.write_text("{ this is not json", encoding="utf-8")

    store = OffsetStore(path)
    store.load()

    assert store.get("anything") == 0


def test_non_numeric_offset_values_are_dropped(tmp_path):
    path = tmp_path / "state.json"
    path.write_text(json.dumps({"good": 10, "bad": "not a number"}), encoding="utf-8")

    store = OffsetStore(path)
    store.load()

    assert store.get("good") == 10
    assert store.get("bad") == 0


def test_save_is_a_noop_when_nothing_changed(tmp_path):
    path = tmp_path / "state.json"
    store = OffsetStore(path)
    store.load()
    store.save()

    assert not path.exists(), "a clean store should not write"


def test_save_force_writes_even_when_clean(tmp_path):
    path = tmp_path / "state.json"
    store = OffsetStore(path)
    store.load()
    store.save(force=True)

    assert path.is_file()


def test_setting_the_same_offset_twice_does_not_redirty(tmp_path):
    path = tmp_path / "state.json"
    store = OffsetStore(path)
    store.set("a", 5)
    store.save()
    path.unlink()

    store.set("a", 5)
    store.save()

    assert not path.exists(), "an unchanged offset should not trigger a rewrite"


def test_save_leaves_no_temp_file_behind(tmp_path):
    path = tmp_path / "state.json"
    store = OffsetStore(path)
    store.set("a", 1)
    store.save()

    assert list(tmp_path.glob("*.tmp")) == []


# ==========================================================================
# Watcher loops: error isolation (PRD section 25)
# ==========================================================================


def _run_one_cycle_then_snapshot(watcher):
    """Let a watcher run one poll cycle, then snapshot health and cancel.

    The snapshot is taken *before* cancelling because cancellation marks the
    watcher `stopped`, which would overwrite the status under test.
    """

    async def _main():
        task = asyncio.create_task(watcher.run())
        await asyncio.sleep(_CYCLE_SECONDS)
        snapshot = registry.snapshot()
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
        except Exception:  # noqa: BLE001 -- teardown only
            pass
        return snapshot

    return asyncio.run(_main())


def test_queue_tailer_submits_mapped_events(temp_home):
    queue = paths.hook_queue_path()
    _append_json_lines(
        queue,
        {
            "session_id": "sess-1",
            "hook_event_name": "SessionStart",
            "_received_at": 1767225600.0,
        },
    )

    pipeline = _CollectingPipeline()
    tailer = QueueTailer(ClaudeAdapter(), pipeline, OffsetStore(tmp_state(temp_home)), queue)
    _run_one_cycle_then_snapshot(tailer)

    assert len(pipeline.events) == 1
    assert pipeline.events[0].session_id == "sess-1"


def test_queue_tailer_reports_itself_degraded_and_keeps_running(temp_home, monkeypatch):
    """A failing cycle must degrade this watcher only -- never propagate."""

    def exploding_read(path, offset):
        raise OSError("queue file is on fire")

    monkeypatch.setattr(queue_tailer, "read_new_lines", exploding_read)

    tailer = QueueTailer(
        ClaudeAdapter(), _CollectingPipeline(), OffsetStore(tmp_state(temp_home))
    )
    snapshot = _run_one_cycle_then_snapshot(tailer)

    assert snapshot[queue_tailer.NAME]["status"] == "degraded"
    assert "queue file is on fire" in snapshot[queue_tailer.NAME]["last_error"]


def test_queue_tailer_reports_healthy_on_a_clean_cycle(temp_home):
    paths.hook_queue_path().parent.mkdir(parents=True, exist_ok=True)

    tailer = QueueTailer(
        ClaudeAdapter(), _CollectingPipeline(), OffsetStore(tmp_state(temp_home))
    )
    snapshot = _run_one_cycle_then_snapshot(tailer)

    assert snapshot[queue_tailer.NAME]["status"] == "running"


def test_transcript_poller_skips_one_unreadable_file_and_continues(temp_home, monkeypatch):
    """One broken transcript must not cost us the other sessions'."""
    root = paths.claude_transcript_root()
    (root / "proj").mkdir(parents=True, exist_ok=True)
    bad = root / "proj" / "bad.jsonl"
    good = root / "proj" / "good.jsonl"
    bad.write_text("", encoding="utf-8")
    _append_json_lines(
        good,
        {
            "type": "assistant",
            "sessionId": "sess-good",
            "message": {
                "model": "claude-sonnet-4-5",
                "usage": {"input_tokens": 10, "output_tokens": 5},
            },
        },
    )

    real_read = transcript_reader.read_new_records

    def selective_read(path, offset=0):
        if Path(path).name == "bad.jsonl":
            raise OSError("permission denied")
        return real_read(path, offset)

    monkeypatch.setattr(transcript_reader, "read_new_records", selective_read)

    pipeline = _CollectingPipeline()
    poller = TranscriptPoller(ClaudeAdapter(), pipeline, OffsetStore(tmp_state(temp_home)))
    snapshot = _run_one_cycle_then_snapshot(poller)

    assert [e.session_id for e in pipeline.events] == ["sess-good"]
    assert snapshot[transcript_poller.NAME]["status"] == "running"


def test_transcript_poller_is_healthy_with_no_transcripts_at_all(temp_home):
    """No Claude Code install is a supported state, not a degraded one."""
    poller = TranscriptPoller(
        ClaudeAdapter(), _CollectingPipeline(), OffsetStore(tmp_state(temp_home))
    )
    snapshot = _run_one_cycle_then_snapshot(poller)

    assert snapshot[transcript_poller.NAME]["status"] == "running"


def tmp_state(home: Path) -> Path:
    """Offset file inside the test's temp home, never the developer's cache."""
    return home / "cache" / "tailer_state.json"
